function showPopup(e,t='info'){const n=document.getElementById('popupNotification');n&&n.remove();const o=document.createElement('div');o.id='popupNotification',o.className=`popup-notification popup-${t}`,o.innerHTML=`<div class="popup-content"><div class="popup-message">${function(e){const t=document.createElement('div');return t.textContent=e,t.innerHTML}(e)}</div><button class="popup-close" onclick="this.parentElement.parentElement.remove()">×</button></div>`,document.body.appendChild(o),setTimeout(()=>{o.parentElement&&o.remove()},5e3)}function escapeHtml(e){const t=document.createElement('div');return t.textContent=e,t.innerHTML}window.alert=function(e){showPopup(e,'info')};
